namespace Fatewake.Infrastructure.Persistence;



/// <summary>Tracks artwork that must be regenerated by a preferred provider after a fallback generation.</summary>

/// <remarks><see href="../../../docs/code/src/Fatewake.Infrastructure/Persistence/ArtRegenerationRecord.md">ArtRegenerationRecord documentation</see>.</remarks>

public sealed class ArtRegenerationRecord

{

    public Guid Id
    {
        get;

        set;

    }
    public Guid? SourceWorkJobId
    {
        get;

        set;

    }

    public Guid? ArtAssetId
    {
        get;

        set;

    }

    public required string VisualFingerprint
    {
        get;

        set;

    }

    public required string RequestJson
    {
        get;

        set;

    }

    public required string TargetProvider
    {
        get;

        set;

    }

    public string? TargetModel
    {
        get;

        set;

    }

    public required string Status
    {
        get;

        set;

    }

    public string? Reason
    {
        get;

        set;

    }

    public Guid? RegenerationWorkJobId
    {
        get;

        set;

    }

    public int AttemptCount
    {
        get;

        set;

    }

    public DateTimeOffset CreatedAt
    {
        get;

        set;

    }

    public DateTimeOffset UpdatedAt
    {
        get;

        set;

    }

    public DateTimeOffset? NextEligibleAt
    {
        get;

        set;

    }

}
